package com.sinat.bubbletoolsync;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;

/**
 * Reads the player's own quests, levels and achievement diary tasks, and shows them in a side panel as a QR code
 * for the OSRS Bubble Tool phone app to scan. Each new reading is also saved to a file, one per account.
 */
@Slf4j
@PluginDescriptor(
	name = "Bubble Tool Sync",
	description = "Shows your quests, levels and diary tasks as a QR code for the OSRS Bubble Tool phone app",
	tags = {"bubble", "phone", "mobile", "qr", "quests", "diaries", "sync"},
	// Needed to save files through RuneLite's Filepath (the folder is .runelite/plugin-data/bubble-tool-sync).
	// The Plugin Hub requires it to match the plugin's file name in the plugin-hub repo: plugins/bubble-tool-sync.
	internalName = "bubble-tool-sync"
)
public class BubbleToolSyncPlugin extends Plugin
{
	/**
	 * While playing, read again at most this often after something changes: 8 game ticks, about 5 seconds.
	 * Game values change all the time, so this stops the plugin reading on every tick.
	 */
	private static final int TICKS_BETWEEN_READS = 8;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	/** RuneLite's shared background worker, used for saving files so the game never waits for the disk. */
	@Inject
	private ScheduledExecutorService executor;

	private SyncPanel panel;
	private NavigationButton navButton;

	// These three are only used on the game's thread.
	/** True when something may have changed since the last reading. */
	private boolean changed;
	/** Game ticks since the last reading. */
	private int ticksSinceRead;
	/** The reading the panel shows now, or null if none yet. */
	private SyncData lastShown;

	@Override
	protected void startUp()
	{
		panel = new SyncPanel(this::readSoon, executor);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Bubble Tool Sync")
			.icon(icon)
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// Read on the first game tick, in case the plugin is switched on while already logged in.
		changed = true;
		ticksSinceRead = TICKS_BETWEEN_READS;
		lastShown = null;
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			changed = true;
		}
	}

	/** A skill's level or experience changed. */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		changed = true;
	}

	/** A game value changed: quest progress, diary tasks and quest points are all kept in these. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		changed = true;
	}

	/** Every game tick (0.6 seconds) while logged in: read again if something changed and it's been long enough. */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		ticksSinceRead++;
		if (changed && ticksSinceRead >= TICKS_BETWEEN_READS)
		{
			read(false);
		}
	}

	/** Called when the panel is opened: read straight away, at the game's next chance. */
	private void readSoon()
	{
		clientThread.invokeLater(() -> read(true));
	}

	/**
	 * Reads everything, and if it's new, shows it in the panel and saves it. Runs on the game's thread.
	 *
	 * @param panelOpened true when the player just opened the panel: then the reading is always shown (with
	 *                    the new time), even if nothing changed
	 */
	private void read(boolean panelOpened)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		SyncData data = SyncData.read(client, Instant.now().getEpochSecond());
		if (data == null)
		{
			// Not fully logged in yet (no name). "changed" stays true, so the next tick tries again.
			return;
		}
		changed = false;
		ticksSinceRead = 0;

		if (!panelOpened && data.hasSameProgressAs(lastShown))
		{
			return;
		}
		String text = data.toText();
		// Only remembered once it has packed without a problem.
		lastShown = data;

		// The panel belongs to Swing's thread, so hand the reading over to it.
		SyncPanel currentPanel = panel;
		if (currentPanel != null)
		{
			SwingUtilities.invokeLater(() -> currentPanel.showData(data, text));
		}

		save(data.getAccountName(), text);
	}

	/**
	 * The saved file's name for an account: "account-" + name + ".txt". The "account-" part matters: Windows
	 * reserves some names (Con, Aux, Nul, Prn, Com1, Lpt1, ...) that are also valid player names, and RuneLite
	 * refuses to make a file called, say, "Con.txt".
	 */
	static String fileNameFor(String accountName)
	{
		return "account-" + accountName + ".txt";
	}

	/**
	 * Saves the QR code's text to {@link #fileNameFor} in the plugin's folder, on the background worker.
	 * It's written to a temporary file first and then swapped in, so the file is never left half-written.
	 */
	private void save(String accountName, String text)
	{
		executor.execute(() ->
		{
			Filepath temp = null;
			try
			{
				Filepath folder = getPluginDirectory();
				folder.createDirectories();
				Filepath file = folder.joinSegment(fileNameFor(accountName));
				temp = folder.createTempFile("saving", ".tmp");
				temp.write(text);
				try
				{
					temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
				}
				catch (AtomicMoveNotSupportedException e)
				{
					// Rare: this drive can't swap in one step, so do a normal replace instead.
					temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
				}
			}
			catch (IOException | IllegalArgumentException e)
			{
				// The account name is left out on purpose: players often share their log when asking for help.
				log.warn("Couldn't save the reading", e);
			}
			finally
			{
				if (temp != null)
				{
					try
					{
						// Only still there if the swap failed.
						temp.deleteIfExists();
					}
					catch (IOException e)
					{
						log.debug("Couldn't delete {}", temp, e);
					}
				}
			}
		});
	}
}

package com.sinat.bubbletoolsync;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;
import java.util.Map;
import java.util.TreeMap;
import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * One reading of the player's progress (levels, quests, diary tasks), and the code that packs it into the
 * text the QR code holds: "BTS1:" followed by the bytes below in base64url (no padding).
 * <p>
 * The layout, "format version 1". The phone app unpacks exactly this layout, so any change here must be made
 * in the app too, and needs a new format version. "Big-endian" means the biggest byte first.
 * <pre>
 * Bytes      What
 * 1          format version (1)
 * 4          when it was read, seconds since 1970 (big-endian, unsigned)
 * 1 + n      account name length in bytes, then the name in UTF-8 (non-breaking spaces turned into spaces)
 * 1          account type (varbit IRONMAN: 0 normal, 1 ironman, 2 ultimate, 3 hardcore, 4 group, ...)
 * 2          quest points (varp QP, big-endian, at most 65,535)
 * 24         real skill levels, in the order of SKILLS (at most 255)
 * 23 x 4     diary varps, in the order of DIARY_VARPS (big-endian)
 * 39         Karamja diary varbits, in the order of KARAMJA_VARBITS (at most 255)
 * varint     number of quests
 * varints    RuneLite quest IDs, smallest first, each as the difference from the one before (the first from 0)
 * ceil(n/4)  quest states, 2 bits each in the same order (0 not started, 1 started, 2 finished),
 *            the first quest in the top two bits of the first byte
 * </pre>
 * Varint: 7 bits per byte, lowest bits first; the top bit set means "more follows".
 * SyncDataTest checks every part of this against examples worked out by hand.
 */
@Getter
@AllArgsConstructor
public final class SyncData
{
	static final int FORMAT_VERSION = 1;
	static final String TEXT_PREFIX = "BTS1:";

	/**
	 * The skills, in the order they're sent. Written out by hand (not Skill.values()) so that a change in
	 * RuneLite can't quietly reorder them. A new skill needs a new format version.
	 */
	static final Skill[] SKILLS = {
		Skill.ATTACK, Skill.DEFENCE, Skill.STRENGTH, Skill.HITPOINTS, Skill.RANGED, Skill.PRAYER, Skill.MAGIC,
		Skill.COOKING, Skill.WOODCUTTING, Skill.FLETCHING, Skill.FISHING, Skill.FIREMAKING, Skill.CRAFTING,
		Skill.SMITHING, Skill.MINING, Skill.HERBLORE, Skill.AGILITY, Skill.THIEVING, Skill.SLAYER, Skill.FARMING,
		Skill.RUNECRAFT, Skill.HUNTER, Skill.CONSTRUCTION, Skill.SAILING,
	};

	/**
	 * The game values ("varps") that hold the achievement diary tasks, one task per bit. Two for each area,
	 * then Karamja's elite tasks.
	 */
	static final int[] DIARY_VARPS = {
		VarPlayerID.ARDOUNGE_ACHIEVEMENT_DIARY, VarPlayerID.ARDOUNGE_ACHIEVEMENT_DIARY2,
		VarPlayerID.DESERT_ACHIEVEMENT_DIARY, VarPlayerID.DESERT_ACHIEVEMENT_DIARY2,
		VarPlayerID.FALADOR_ACHIEVEMENT_DIARY, VarPlayerID.FALADOR_ACHIEVEMENT_DIARY2,
		VarPlayerID.FREMENNIK_ACHIEVEMENT_DIARY, VarPlayerID.FREMENNIK_ACHIEVEMENT_DIARY2,
		VarPlayerID.KANDARIN_ACHIEVEMENT_DIARY, VarPlayerID.KANDARIN_ACHIEVEMENT_DIARY2,
		VarPlayerID.KOUREND_ACHIEVEMENT_DIARY, VarPlayerID.KOUREND_ACHIEVEMENT_DIARY2,
		VarPlayerID.LUMB_DRAY_ACHIEVEMENT_DIARY, VarPlayerID.LUMB_DRAY_ACHIEVEMENT_DIARY2,
		VarPlayerID.MORYTANIA_ACHIEVEMENT_DIARY, VarPlayerID.MORYTANIA_ACHIEVEMENT_DIARY2,
		VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, VarPlayerID.VARROCK_ACHIEVEMENT_DIARY2,
		VarPlayerID.WESTERN_ACHIEVEMENT_DIARY, VarPlayerID.WESTERN_ACHIEVEMENT_DIARY2,
		VarPlayerID.WILDERNESS_ACHIEVEMENT_DIARY, VarPlayerID.WILDERNESS_ACHIEVEMENT_DIARY2,
		VarPlayerID.ATJUN_TASKS_4,
	};

	/**
	 * Karamja's easy, medium and hard tasks are kept in their own small game values ("varbits") instead of
	 * bits of a varp. In the order Quest Helper lists them.
	 */
	static final int[] KARAMJA_VARBITS = {
		VarbitID.ATJUN_EASY_BANANA, VarbitID.ATJUN_EASY_SWING, VarbitID.ATJUN_EASY_GOLD,
		VarbitID.ATJUN_EASY_BOAT_SARIM, VarbitID.ATJUN_EASY_BOAT_ARDY, VarbitID.ATJUN_EASY_CAIRN,
		VarbitID.ATJUN_EASY_FISHING, VarbitID.ATJUN_EASY_SEAWEED, VarbitID.ATJUN_EASY_TZHAAR,
		VarbitID.ATJUN_EASY_JOGRE,
		VarbitID.ATJUN_HARD_FIGHTPITS, VarbitID.ATJUN_HARD_FIGHTCAVE, VarbitID.ATJUN_HARD_OOMLIE,
		VarbitID.ATJUN_HARD_NATURE, VarbitID.ATJUN_HARD_KARAMBWAN, VarbitID.ATJUN_HARD_DEATHWING,
		VarbitID.ATJUN_HARD_XBOW, VarbitID.ATJUN_HARD_PALM, VarbitID.ATJUN_HARD_DURADEL,
		VarbitID.ATJUN_HARD_DRAGON,
		VarbitID.ATJUN_MED_AGILITY, VarbitID.ATJUN_MED_VOLCANO, VarbitID.ATJUN_MED_CRANDOR,
		VarbitID.ATJUN_MED_CART, VarbitID.ATJUN_MED_CLEANUP, VarbitID.ATJUN_MED_SPIDER,
		VarbitID.ATJUN_MED_TOPAZ, VarbitID.ATJUN_MED_TEAK, VarbitID.ATJUN_MED_MAHOGANY,
		VarbitID.ATJUN_MED_KARAMBWAN, VarbitID.ATJUN_MED_MACHETTE, VarbitID.ATJUN_MED_GLIDER,
		VarbitID.ATJUN_MED_FARMING, VarbitID.ATJUN_MED_GRAAHK, VarbitID.ATJUN_MED_SHILO_VINES,
		VarbitID.ATJUN_MED_SHILO_LAVA, VarbitID.ATJUN_MED_SHILO_STAIRS, VarbitID.ATJUN_MED_KHAZARD,
		VarbitID.ATJUN_MED_CHARTER,
	};

	/** Quest states as sent: 2 bits each. */
	static final int QUEST_NOT_STARTED = 0;
	static final int QUEST_STARTED = 1;
	static final int QUEST_FINISHED = 2;

	/** When this was read, in seconds since 1 January 1970. */
	private final long readAt;
	private final String accountName;
	/** 0 normal, 1 ironman, 2 ultimate, 3 hardcore, 4 group ironman, and so on (varbit IRONMAN). */
	private final int accountType;
	/** The game's own quest point total (varp QP), so the app matches the game even before it knows a new quest. */
	private final int questPoints;
	/** One level per skill, in the order of {@link #SKILLS}. */
	private final int[] skillLevels;
	/** One value per varp, in the order of {@link #DIARY_VARPS}. */
	private final int[] diaryVarps;
	/** One value per varbit, in the order of {@link #KARAMJA_VARBITS}. */
	private final int[] karamjaVarbits;
	/** RuneLite's quest IDs, smallest first. */
	private final int[] questIds;
	/** One state per quest, in the same order as {@link #questIds}: 0, 1 or 2 (see QUEST_ constants). */
	private final int[] questStates;

	/**
	 * Reads everything from the game. Must run on the client thread (quest states come from a game script).
	 *
	 * @return the reading, or null if the player isn't fully logged in yet
	 */
	static SyncData read(Client client, long nowSeconds)
	{
		Player player = client.getLocalPlayer();
		String name = player == null ? null : player.getName();
		if (name == null || name.isEmpty())
		{
			return null;
		}
		// The game uses a "non-breaking space" in some names; turn it back into a normal space.
		name = name.replace(' ', ' ');

		int[] levels = new int[SKILLS.length];
		for (int i = 0; i < SKILLS.length; i++)
		{
			levels[i] = client.getRealSkillLevel(SKILLS[i]);
		}

		int[] varps = new int[DIARY_VARPS.length];
		for (int i = 0; i < DIARY_VARPS.length; i++)
		{
			varps[i] = client.getVarpValue(DIARY_VARPS[i]);
		}

		int[] karamja = new int[KARAMJA_VARBITS.length];
		for (int i = 0; i < KARAMJA_VARBITS.length; i++)
		{
			karamja[i] = client.getVarbitValue(KARAMJA_VARBITS[i]);
		}

		// Every quest RuneLite knows about, so new quests are sent without changing this plugin.
		// A TreeMap keeps them sorted by ID.
		Map<Integer, Integer> quests = new TreeMap<>();
		for (Quest quest : Quest.values())
		{
			int state;
			switch (quest.getState(client))
			{
				case FINISHED:
					state = QUEST_FINISHED;
					break;
				case IN_PROGRESS:
					state = QUEST_STARTED;
					break;
				default:
					state = QUEST_NOT_STARTED;
					break;
			}
			quests.put(quest.getId(), state);
		}
		int[] questIds = new int[quests.size()];
		int[] questStates = new int[quests.size()];
		int i = 0;
		for (Map.Entry<Integer, Integer> entry : quests.entrySet())
		{
			questIds[i] = entry.getKey();
			questStates[i] = entry.getValue();
			i++;
		}

		return new SyncData(nowSeconds, name, client.getVarbitValue(VarbitID.IRONMAN),
			client.getVarpValue(VarPlayerID.QP), levels, varps, karamja, questIds, questStates);
	}

	/**
	 * True if the other reading has exactly the same progress as this one: everything except when it was read.
	 * Used to skip showing and saving a reading when nothing has really changed.
	 */
	boolean hasSameProgressAs(SyncData other)
	{
		return other != null
			&& accountName.equals(other.accountName)
			&& accountType == other.accountType
			&& questPoints == other.questPoints
			&& Arrays.equals(skillLevels, other.skillLevels)
			&& Arrays.equals(diaryVarps, other.diaryVarps)
			&& Arrays.equals(karamjaVarbits, other.karamjaVarbits)
			&& Arrays.equals(questIds, other.questIds)
			&& Arrays.equals(questStates, other.questStates);
	}

	/** Packs this reading into bytes, in the layout described at the top. */
	byte[] pack()
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream(512);

		out.write(FORMAT_VERSION);
		writeInt(out, readAt);

		byte[] nameBytes = accountName.getBytes(StandardCharsets.UTF_8);
		if (nameBytes.length > 255)
		{
			throw new IllegalArgumentException("Account name is too long");
		}
		out.write(nameBytes.length);
		out.write(nameBytes, 0, nameBytes.length);

		out.write(toByte(accountType));

		// Quest points: 2 bytes, biggest first, kept within 0 to 65,535.
		int points = Math.max(0, Math.min(0xFFFF, questPoints));
		out.write(points >>> 8);
		out.write(points & 0xFF);

		checkLength(skillLevels, SKILLS.length, "skill levels");
		for (int level : skillLevels)
		{
			out.write(toByte(level));
		}

		checkLength(diaryVarps, DIARY_VARPS.length, "diary varps");
		for (int value : diaryVarps)
		{
			writeInt(out, value);
		}

		checkLength(karamjaVarbits, KARAMJA_VARBITS.length, "Karamja varbits");
		for (int value : karamjaVarbits)
		{
			out.write(toByte(value));
		}

		checkLength(questStates, questIds.length, "quest states");
		writeVarint(out, questIds.length);
		int previousId = 0;
		for (int id : questIds)
		{
			if (id < previousId)
			{
				throw new IllegalArgumentException("Quest IDs must be sorted, smallest first");
			}
			writeVarint(out, id - previousId);
			previousId = id;
		}

		// Four quest states per byte, the first quest in the top two bits.
		byte[] states = new byte[(questStates.length + 3) / 4];
		for (int q = 0; q < questStates.length; q++)
		{
			int shift = 6 - 2 * (q % 4);
			states[q / 4] |= (byte) ((questStates[q] & 0b11) << shift);
		}
		out.write(states, 0, states.length);

		return out.toByteArray();
	}

	/** The text that goes in the QR code (and in the saved file): "BTS1:" and the packed bytes in base64url. */
	String toText()
	{
		return TEXT_PREFIX + Base64.getUrlEncoder().withoutPadding().encodeToString(pack());
	}

	/** Writes the lowest 4 bytes of a number, biggest byte first. */
	private static void writeInt(ByteArrayOutputStream out, long value)
	{
		out.write((int) (value >>> 24) & 0xFF);
		out.write((int) (value >>> 16) & 0xFF);
		out.write((int) (value >>> 8) & 0xFF);
		out.write((int) value & 0xFF);
	}

	/** Writes a number 7 bits at a time, lowest bits first; the top bit of each byte means "more follows". */
	private static void writeVarint(ByteArrayOutputStream out, int value)
	{
		if (value < 0)
		{
			throw new IllegalArgumentException("Varints can't be negative");
		}
		while (value >= 0x80)
		{
			out.write((value & 0x7F) | 0x80);
			value >>>= 7;
		}
		out.write(value);
	}

	/** Keeps a number within one byte (0 to 255): anything bigger is sent as 255. */
	private static int toByte(int value)
	{
		return Math.max(0, Math.min(255, value));
	}

	private static void checkLength(int[] values, int expected, String what)
	{
		if (values.length != expected)
		{
			throw new IllegalArgumentException("Expected " + expected + " " + what + ", got " + values.length);
		}
	}
}

package com.sinat.bubbletoolsync;

import com.sinat.bubbletoolsync.qr.QrCode;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.io.IOException;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ScheduledExecutorService;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.Filepath;

/**
 * The side panel: the account name, when it was read, the QR code, and "Copy text" and "Export file" buttons.
 * Everything here runs on Swing's thread (the "EDT"), never the game's.
 */
@Slf4j
class SyncPanel extends PluginPanel
{
	private static final DateTimeFormatter READ_AT_FORMAT =
		DateTimeFormatter.ofPattern("d MMM yyyy, HH:mm", Locale.ENGLISH);
	/** Space around the panel's edges, in pixels. */
	private static final int SIDE_GAP = 6;

	private final Runnable onOpen;
	/** RuneLite's background worker, for writing exported files without freezing the panel. */
	private final ScheduledExecutorService executor;

	private final JLabel nameLabel = new JLabel();
	private final JLabel questPointsLabel = new JLabel();
	private final JLabel readAtLabel = new JLabel();
	private final QrView qrView = new QrView();
	private final JButton copyButton = new JButton("Copy text");
	private final JButton exportButton = new JButton("Export file");
	private final JLabel messageLabel = new JLabel();

	/** The text in the QR code right now, or null if there isn't one yet. */
	private String text;
	/** The account the text belongs to, for the exported file's suggested name. */
	private String accountName;

	/**
	 * @param onOpen   what to do each time the player opens this panel (the plugin reads the game again)
	 * @param executor RuneLite's background worker, used to write exported files
	 */
	SyncPanel(Runnable onOpen, ScheduledExecutorService executor)
	{
		// false: no scroll bar, so the QR code can use the panel's full width.
		super(false);
		this.onOpen = onOpen;
		this.executor = executor;

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(SIDE_GAP, SIDE_GAP, SIDE_GAP, SIDE_GAP));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Bubble Tool Sync");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);

		nameLabel.setFont(FontManager.getRunescapeBoldFont());
		nameLabel.setForeground(ColorScheme.BRAND_ORANGE);
		questPointsLabel.setFont(FontManager.getRunescapeSmallFont());
		questPointsLabel.setForeground(Color.WHITE);
		readAtLabel.setFont(FontManager.getRunescapeSmallFont());
		readAtLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		// One line each, top to bottom.
		JPanel top = new JPanel(new GridLayout(0, 1, 0, 2));
		top.setOpaque(false);
		top.add(title);
		top.add(nameLabel);
		top.add(questPointsLabel);
		top.add(readAtLabel);

		messageLabel.setFont(FontManager.getRunescapeSmallFont());
		messageLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		messageLabel.setHorizontalAlignment(SwingConstants.CENTER);

		copyButton.setFocusable(false);
		copyButton.setToolTipText("Copies the text inside the QR code");
		copyButton.addActionListener(e -> copyText());

		exportButton.setFocusable(false);
		exportButton.setToolTipText("Saves the text inside the QR code to a file, in a folder you choose");
		exportButton.addActionListener(e -> exportFile());

		// The two buttons side by side.
		JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
		buttons.setOpaque(false);
		buttons.add(copyButton);
		buttons.add(exportButton);

		JPanel bottom = new JPanel(new BorderLayout(0, 6));
		bottom.setOpaque(false);
		bottom.add(buttons, BorderLayout.NORTH);
		bottom.add(messageLabel, BorderLayout.SOUTH);

		// Everything stacked at the top of the panel.
		JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setOpaque(false);
		content.add(top, BorderLayout.NORTH);
		content.add(qrView, BorderLayout.CENTER);
		content.add(bottom, BorderLayout.SOUTH);
		add(content, BorderLayout.NORTH);

		showNothing();
	}

	/**
	 * Shows a new reading.
	 *
	 * @param newText the reading packed as text ({@link SyncData#toText()})
	 */
	void showData(SyncData data, String newText)
	{
		accountName = data.getAccountName();
		QrCode qr;
		try
		{
			// LOW error correction keeps the code as small as possible; a screen gives a clean picture.
			// The generator raises it for free if there's room.
			qr = QrCode.encodeText(newText, QrCode.Ecc.LOW);
		}
		catch (RuntimeException e)
		{
			// Shouldn't happen (a QR code holds about 2,900 bytes; ours is about 600), but don't crash the panel.
			showMessage("Couldn't make the QR code. Use Copy text instead.");
			text = newText;
			copyButton.setEnabled(true);
			exportButton.setEnabled(true);
			return;
		}

		text = newText;
		nameLabel.setText(data.getAccountName());
		questPointsLabel.setText("Quest points: " + data.getQuestPoints());
		readAtLabel.setText("Read " + READ_AT_FORMAT.format(
			Instant.ofEpochSecond(data.getReadAt()).atZone(ZoneId.systemDefault())));
		qrView.setQr(qr);
		copyButton.setEnabled(true);
		exportButton.setEnabled(true);
		messageLabel.setText("Scan with Bubble Tool on your phone");
	}

	/** Shows a message in place of the QR code, for example before the player logs in. */
	void showNothing()
	{
		text = null;
		accountName = null;
		nameLabel.setText(" ");
		questPointsLabel.setText(" ");
		readAtLabel.setText(" ");
		qrView.setQr(null);
		copyButton.setEnabled(false);
		exportButton.setEnabled(false);
		messageLabel.setText("Log in to the game to see your QR code");
	}

	private void showMessage(String message)
	{
		qrView.setQr(null);
		messageLabel.setText(message);
	}

	private void copyText()
	{
		if (text != null)
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
			messageLabel.setText("Copied");
		}
	}

	/**
	 * Asks where to save, then writes the same text as the QR code to that file (UTF-8, one line, no line break
	 * at the end), for the Bubble Tool app to import.
	 */
	private void exportFile()
	{
		if (text == null)
		{
			return;
		}
		// Keep the text as it is now, in case a new reading arrives while the dialog is open.
		String exportText = text;

		// RuneLite's own file chooser (Plugin Hub plugins must use it instead of Java's JFileChooser).
		Filepath.Chooser chooser = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Export for Bubble Tool")
			.addExtensionFilter("Text file (*.txt)", "txt")
			.setDefaultExtension("txt")
			.setFileName(BubbleToolSyncPlugin.fileNameFor(accountName));
		List<Filepath> chosen = chooser.showDialog(this);
		if (chosen == null || chosen.isEmpty())
		{
			// The player cancelled.
			return;
		}
		Filepath file = chosen.get(0);

		if (file.exists())
		{
			int answer = JOptionPane.showConfirmDialog(this,
				file.getFileName() + " already exists. Replace it?", "Export for Bubble Tool",
				JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
			if (answer != JOptionPane.YES_OPTION)
			{
				return;
			}
		}

		messageLabel.setText("Exporting...");
		executor.execute(() ->
		{
			String result;
			try
			{
				file.write(exportText);
				result = "Exported " + file.getFileName();
			}
			catch (IOException e)
			{
				log.warn("Couldn't export the file", e);
				result = "Couldn't export the file";
			}
			String message = result;
			SwingUtilities.invokeLater(() -> messageLabel.setText(message));
		});
	}

	@Override
	public void onActivate()
	{
		onOpen.run();
	}

	/**
	 * Draws the QR code as big as the panel allows: black squares on white, with the white border ("quiet zone")
	 * of 4 squares that QR scanners need around the code.
	 */
	private static class QrView extends JComponent
	{
		private static final int QUIET_ZONE = 4;

		private QrCode qr;

		QrView()
		{
			// Square, filling the panel's width. Without a scroll bar the panel is PANEL_WIDTH + SCROLLBAR_WIDTH
			// wide; take off the gaps on both sides.
			int side = PANEL_WIDTH + SCROLLBAR_WIDTH - 2 * SIDE_GAP;
			setPreferredSize(new Dimension(side, side));
		}

		void setQr(QrCode qr)
		{
			this.qr = qr;
			setVisible(qr != null);
			revalidate();
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			if (qr == null)
			{
				return;
			}

			int side = Math.min(getWidth(), getHeight());
			int left = (getWidth() - side) / 2;
			int top = (getHeight() - side) / 2;
			int cells = qr.size + 2 * QUIET_ZONE;

			g.setColor(Color.WHITE);
			g.fillRect(left, top, side, side);

			// Each square's edges are worked out from the whole size, so the squares fill the space exactly
			// with no gaps, even when the size doesn't divide evenly.
			g.setColor(Color.BLACK);
			for (int y = 0; y < qr.size; y++)
			{
				int y0 = top + (y + QUIET_ZONE) * side / cells;
				int y1 = top + (y + QUIET_ZONE + 1) * side / cells;
				for (int x = 0; x < qr.size; x++)
				{
					if (qr.getModule(x, y))
					{
						int x0 = left + (x + QUIET_ZONE) * side / cells;
						int x1 = left + (x + QUIET_ZONE + 1) * side / cells;
						g.fillRect(x0, y0, x1 - x0, y1 - y0);
					}
				}
			}
		}
	}
}

